def _nearest(key, candidates):
    best, best_dist = candidates[0], None
    for i in candidates:
        cached = _KEYS[i]
        dist = 0.0
        for v, w, log2, span in zip(key, cached, _LOG, _SPAN):
            if log2:
                dist += abs(math.log2(max(v, 1)) - math.log2(max(w, 1)))
            else:
                dist += abs(v - w) / span
        if best_dist is None or dist < best_dist:
            best, best_dist = i, dist
    return best


def key_kernel_helion_v13_attention(*args) -> int:
    """Config index for the given arguments (also serves as cache key)."""
    key = _key(args)
    index = _INDEX.get(key)
    if index is not None:
        return index
    primary = key[:_NPRIMARY]
    same = [i for i, k in enumerate(_KEYS) if k[:_NPRIMARY] == primary]
    return _nearest(key, same or list(range(len(_KEYS))))


def autotune_kernel_helion_v13_attention(*args) -> dict:
    """Select the optimal config for the given arguments."""
    return _CONFIGS[key_kernel_helion_v13_attention(*args)]
